<template><view class="safety"><text class="heading">材料与工具安全</text><text v-if="loading">正在读取安全说明…</text><template v-else-if="data"><text class="label">{{data.medium?data.medium+' · ':''}}{{labels[data.level]||'尚未标注'}}</text><text v-if="data.hazards">注意事项：{{data.hazards}}</text><text>{{data.guidance}}</text><text v-if="data.source" class="source">标注依据：{{data.source}}</text></template><text v-else @click="load">安全说明暂时无法加载，请点击重试，并向带领者确认材料与工具。</text></view></template>
<script setup>import{ref,watch}from'vue';import{request}from'../utils/request';const props=defineProps({projectId:[String,Number]});const data=ref(null),loading=ref(false);const labels={LOW:'常规注意',GUIDED:'需在指导下操作',HIGH:'高风险工具 / 材料',UNKNOWN:'尚未完成安全标注'};async function load(){if(!props.projectId)return;loading.value=true;try{data.value=await request({url:'/api/growth/safety/'+props.projectId})}catch{data.value=null}finally{loading.value=false}}watch(()=>props.projectId,load,{immediate:true})</script>
<style scoped>.safety{margin:24rpx;padding:28rpx;background:var(--zy-card-bg,#fff);border:1rpx solid var(--zy-border,#dce5e3);border-radius:20rpx;display:flex;flex-direction:column;gap:16rpx;font-size:26rpx;line-height:1.8;color:var(--zy-content,#4b635d)}.heading{font-size:32rpx;font-weight:600;color:var(--zy-title,#253f36)}.label{color:#98622b}.source{font-size:23rpx;color:var(--zy-aid,#70857a)}</style>
